/* aesthetic interval v2.19.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-space-2: 0.5em;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-ci {
position: relative;
  height: 1.6em;
}

.ae-ci::before {
/* the shared baseline rule the interval sits on */
  content: '';
  position: absolute;
  inset: 50% 0 auto;
  height: 1px;
  background: var(--ae-line);
}

.ae-ci-band {
position: absolute;
  top: 50%;
  height: 10px;
  transform: translateY(-50%);
  transform-origin: center;
  background: color-mix(in oklab, var(--ae-ink) 9%, var(--ae-surface));
  border: 1px solid var(--ae-ink-faint);
  animation: ae-ci-draw var(--ae-soft) var(--ae-ease) both;
}

.ae-ci-mean {
position: absolute;
  top: 50%;
  width: 2px;
  height: 1.15em;
  transform: translate(-50%, -50%);
  background: var(--ae-ink);
}

.ae-ci.is-lead .ae-ci-mean {
background: var(--ae-accent);
}

.ae-ci-whisker {
position: absolute;
  top: 50%;
  height: 1px;
  transform: translateY(-50%);
  background: var(--ae-ink-muted);
}

.ae-ci-cap {
position: absolute;
  top: 50%;
  width: 1px;
  height: 0.8em;
  transform: translate(-50%, -50%);
  background: var(--ae-ink-muted);
}

.ae-ci-detail {
position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: baseline;
  gap: var(--ae-space-2);
  padding: 0.1em 0.2em 0.1em 0.7em;
  background: var(--ae-surface);
  font-family: var(--ae-font-mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: var(--ae-ink);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--ae-quick) var(--ae-ease);
}

.ae-ci-detail .ae-ci-bound {
color: var(--ae-ink-faint);
}

.ae-ci:hover .ae-ci-detail,
.ae-ci:focus-within .ae-ci-detail {
opacity: 1;
}

@media (hover: none) {
  .ae-ci-detail {
  opacity: 1;
  }
}

@keyframes ae-ci-draw {
from {
    transform: translateY(-50%) scaleX(0.04);
  }
}
